import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  it('rejects a value outside a declared enum naming the property path and constraint', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'set_units',
        description: 'Choose units',
        inputSchema: {
          type: 'object',
          properties: {units: {type: 'string', enum: ['metric', 'imperial']}},
        },
      },
      async () => {
        executorCalls += 1;
        return 'ok';
      }
    );

    const response = await registry.execute('set_units', {units: 'kelvin-secret'});

    expect({
      executorCalls,
      namesPath: response.result.includes('/units'),
      namesConstraint: response.result.includes('enum'),
      leaksValue: response.result.includes('kelvin-secret'),
    }).toEqual({executorCalls: 0, namesPath: true, namesConstraint: true, leaksValue: false});
  });

  it('passes valid input with an unlisted extra property to the executor unchanged, once', async () => {
    const registry = new ToolRegistry();
    const received: Record<string, unknown>[] = [];
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async input => {
        received.push(input);
        return 'sunny';
      }
    );

    const response = await registry.execute('get_weather', {location: 'Paris', extra: 7});

    expect({received, result: response.result}).toEqual({
      received: [{location: 'Paris', extra: 7}],
      result: 'sunny',
    });
  });

  it('throws Unknown tool for a name that was never registered', async () => {
    const registry = new ToolRegistry();

    await expect(registry.execute('missing_tool', {})).rejects.toThrow('Unknown tool: missing_tool');
  });
});
1:# Tool Input Validation
10:## Validation at execute time
12:- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the missing property as required and never invokes the executor ([validated by: rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.acceptance.test.ts#L16)).
13:- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the failing field path and expected type without invoking the executor, and neither `result` nor the emitted log record contains the offending property value ([validated by: rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L46)).
14:- When `input` supplies a value outside a property's declared `enum`, `ToolRegistry.execute` returns a `ToolResponse` naming the failing property path and the `enum` constraint without invoking the executor or echoing the value ([validated by: rejects a value outside a declared enum naming the property path and constraint](../../src/orchestration/tools/registry.test.ts#L4)).
15:- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting `additionalProperties: false`, coercing types or applying defaults ([validated by: passes valid input with an unlisted extra property to the executor unchanged, once](../../src/orchestration/tools/registry.test.ts#L32)).
16:- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake ([validated by: throws Unknown tool for a name that was never registered](../../src/orchestration/tools/registry.test.ts#L59)).
